<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {ElMessage} from 'element-plus';
import {api,formatTime} from '../api';
import {device} from '../composables/device';
import {preferences} from '../composables/preferences';
import {registerPageRefresher} from '../composables/pageRefresh';
import {usePagination} from '../composables/pagination';
import {dateKey,exportRangeError,logsInRange,logText,logsWorkbook,saveFile} from '../composables/logExport';
const records=ref([]),error=ref(''),detail=ref(null),detailOpen=ref(false),onlyErrors=ref(false),category=ref('all'),dateFilter=ref('all');let timer,unregister;
const categories=computed(()=>[...new Set(records.value.map(r=>r.category))]),errorCount=computed(()=>records.value.filter(r=>r.failed).length);
const filtered=computed(()=>records.value.filter(r=>(!onlyErrors.value||r.failed)&&(category.value==='all'||r.category===category.value)&&(dateFilter.value==='all'||new Date(r.time).toDateString()===new Date().toDateString())));
const {page,pageSize,visible}=usePagination(filtered);
const exportOpen=ref(false),exportLoading=ref(false),exporting=ref(false),exportRecords=ref([]),exportError=ref(''),exportMode=ref('all'),startDate=ref(''),endDate=ref('');
const rangeError=computed(()=>exportRangeError(exportMode.value,startDate.value,endDate.value));
const exportRows=computed(()=>logsInRange(exportRecords.value,exportMode.value,startDate.value,endDate.value));
const snapshot=computed(()=>device.snapshot||{});
const temp=computed(()=>{const a=(snapshot.value.cpu?.temperatures||[]).filter(r=>/^(thermal_cluster|cluster\d+_thermal)/.test(r.type));return a.length?(a.reduce((s,r)=>s+Number(r.celsius),0)/a.length).toFixed(1):'—';});
const frequency=computed(()=>(snapshot.value.cpu?.policies||[]).map(r=>(r.frequency_mhz/1000).toFixed(2)).join(' / ')||'—');
async function load(){if(document.hidden&&preferences.pauseBackground)return;try{const data=await api('/api/studio/logs',{signal:AbortSignal.timeout(10000)});records.value=data.records||[];error.value='';}catch{error.value='日志读取失败，请重试。';}}
function open(row){detail.value=row;detailOpen.value=true;}
function download(row){saveFile(new Blob([logText(row,snapshot.value)],{type:'text/plain;charset=utf-8'}),'运行记录-'+String(row.time||Date.now()).replace(/[:\/]/g,'-')+'.txt');ElMessage.success('TXT 记录已下载');}
async function loadExport(){exportLoading.value=true;exportError.value='';try{const data=await api('/api/studio/logs?export=1',{signal:AbortSignal.timeout(20000)});exportRecords.value=data.records||[];if(!startDate.value){const dates=exportRecords.value.map(row=>dateKey(row.time)).filter(Boolean).sort();startDate.value=dates[0]||dateKey(new Date());endDate.value=dates.at(-1)||dateKey(new Date());}}catch{exportError.value='记录读取失败，请重试。';}finally{exportLoading.value=false;}}
function openExport(){exportOpen.value=true;loadExport();}
async function exportAll(){if(exporting.value||exportLoading.value||exportError.value||rangeError.value||!exportRows.value.length)return;exporting.value=true;const rows=[...exportRows.value],period=exportMode.value==='all'?'全部日期':startDate.value+'至'+endDate.value;try{const blob=await logsWorkbook(rows,JSON.parse(JSON.stringify(snapshot.value)));saveFile(blob,'运行记录-'+period+'.xlsx');ElMessage.success('已导出 '+rows.length+' 条记录');exportOpen.value=false;}catch{ElMessage.error('导出失败，请重试。');}finally{exporting.value=false;}}
onMounted(()=>{load();timer=setInterval(load,15000);unregister=registerPageRefresher('logs',load);});onBeforeUnmount(()=>{clearInterval(timer);unregister?.();});
</script>
<template>
<UiCard title="运行记录" glyph="file" class="table-card">
 <div class="table-tools logs-filters"><div class="tabbar"><button class="tab" :class="{active:!onlyErrors}" @click="onlyErrors=false;page=1">全部记录 {{records.length}}</button><button class="tab" :class="{active:onlyErrors}" @click="onlyErrors=true;page=1">异常记录 <span class="red">{{errorCount}}</span></button></div><select v-model="dateFilter" aria-label="日期筛选" @change="page=1"><option value="all">全部日期</option><option value="today">今天</option></select><select v-model="category" aria-label="类别筛选" @change="page=1"><option value="all">全部类别</option><option v-for="kind in categories" :key="kind" :value="kind">{{kind}}</option></select><button class="btn primary logs-export-button" @click="openExport"><UiIcon name="download" :size="15"/>一键导出所有记录</button></div>
 <div class="log-table rich-logs"><table><thead><tr><th>记录时间</th><th>类别 / 来源</th><th>记录内容</th><th>结果</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td class="time-cell number">{{formatTime(row.time,{seconds:true})}}</td><td><b>{{row.category}}</b><small>{{row.source_label}}</small></td><td class="summary-cell"><b>{{row.summary}}</b><small>{{row.description}}</small></td><td><span class="badge" :class="row.failed?'red':'green'">{{row.failed?'异常':'正常'}}</span></td><td><div class="row-actions"><button class="btn plain" @click="open(row)"><UiIcon name="eye" :size="15"/>查看</button><button class="btn plain" @click="download(row)"><UiIcon name="download" :size="15"/>下载</button></div></td></tr></tbody></table><div v-if="!visible.length" class="empty-state">{{error||'暂无符合条件的记录'}}</div></div><UiPagination v-model="page" v-model:page-size="pageSize" :total="filtered.length"/>
</UiCard>
<UiModal v-model="exportOpen" title="导出运行记录" width="min(560px,92vw)"><form id="logs-export-form" class="logs-export-form" @submit.prevent="exportAll"><div class="export-scope" role="group" aria-label="导出日期范围"><label :class="{active:exportMode==='all'}"><input v-model="exportMode" type="radio" value="all" :disabled="exporting">全部日期</label><label :class="{active:exportMode==='range'}"><input v-model="exportMode" type="radio" value="range" :disabled="exporting">自定义时间段</label></div><div class="field-row export-date-fields"><div class="field"><label for="export-start">开始日期</label><input id="export-start" v-model="startDate" type="date" :disabled="exportMode==='all'||exporting" :aria-invalid="Boolean(rangeError)" aria-describedby="export-range-message"></div><div class="field"><label for="export-end">结束日期</label><input id="export-end" v-model="endDate" type="date" :disabled="exportMode==='all'||exporting" :min="startDate||undefined" :aria-invalid="Boolean(rangeError)" aria-describedby="export-range-message"></div></div><div id="export-range-message" class="export-range-message" :class="{red:rangeError}" role="status">{{rangeError||'包含开始和结束日期当天的全部记录。'}}</div><div v-if="exportError" class="note error" role="alert">{{exportError}}<button type="button" class="btn" @click="loadExport">重新读取</button></div><div v-else class="export-summary" role="status"><span class="icon-box"><UiIcon name="file" :size="20"/></span><div><b>{{exportLoading?'正在读取记录…':rangeError?'请调整日期范围':exportRows.length?'将导出 '+exportRows.length+' 条记录':'所选时间段暂无记录'}}</b><small>Excel 表格（.xlsx） · 包含全部分页的记录</small></div></div></form><template #footer><button class="btn" :disabled="exporting" @click="exportOpen=false">取消</button><button class="btn primary" type="submit" form="logs-export-form" :disabled="exportLoading||exporting||Boolean(exportError)||Boolean(rangeError)||!exportRows.length"><UiIcon name="download" :size="15"/>{{exporting?'正在导出…':'导出 Excel'}}</button></template></UiModal>
<UiModal v-model="detailOpen" title="记录详情" width="min(760px,92vw)"><template v-if="detail"><div class="modal-heading"><span class="icon-box"><UiIcon name="file"/></span><div><b>{{detail.summary}}</b><small>{{formatTime(detail.time,{seconds:true})}} · {{detail.category}}</small></div><span class="badge" :class="detail.failed?'red':'green'">{{detail.failed?'异常':'正常'}}</span></div><img v-if="detail.image_url" class="log-detail-img" :src="detail.image_url" alt="本条记录关联的仪表或现场图片"><div class="modal-info"><div class="kv-row"><span>事件说明</span><b>{{detail.description}}</b></div><div class="kv-row"><span>记录来源</span><b>{{detail.source_label}}</b></div><div v-if="detail.value" class="kv-row"><span>仪表读数</span><b :class="detail.failed?'red':'green'">{{detail.value}}</b></div></div><div class="section-label">当前设备信息<small>{{formatTime(snapshot.sampled_at,{seconds:true})}}</small></div><div class="log-snapshot"><div><small>处理器平均温度</small><b>{{temp}} °C</b></div><div><small>处理器频率</small><b>{{frequency}} GHz</b></div><div><small>处理器占用</small><b>{{snapshot.cpu?.usage_percent??'—'}} %</b></div></div><p class="subtle">该条历史记录未保存当时的设备快照。</p></template><template #footer><button class="btn" @click="detailOpen=false">关闭</button><button class="btn primary" :disabled="!detail" @click="download(detail)"><UiIcon name="download" :size="15"/>下载这条记录</button></template></UiModal>
</template>
